{
  "name": "opencode-okf-context",
  "version": "0.3.0",
  "description": "OpenCode plugin: progressive disclosure + auto-unload for OKF (Open Knowledge Format) knowledge bundles. Inspired by DCP's outbound-only context transformation.",
  "type": "module",
  "license": "MIT",
  "author": "likai-hust",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/likai-hust/opencode-okf-context.git"
  },
  "homepage": "https://github.com/likai-hust/opencode-okf-context#readme",
  "bugs": {
    "url": "https://github.com/likai-hust/opencode-okf-context/issues"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "okf",
    "open-knowledge-format",
    "progressive-disclosure",
    "context-management",
    "context-window",
    "knowledge-management",
    "knowledge-base",
    "llm",
    "agent"
  ],
  "main": "./dist/index.js",
  "module": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "bin": {
    "okf": "./dist/cli.js"
  },
  "engines": {
    "node": ">=18"
  },
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    },
    "./cli": {
      "types": "./dist/cli.d.ts",
      "import": "./dist/cli.js"
    },
    "./package.json": "./package.json"
  },
  "files": [
    "dist",
    "okf.schema.json",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "build": "tsup && tsc -p tsconfig.build.json",
    "test": "bun test",
    "typecheck": "tsc --noEmit",
    "prepublishOnly": "bun run build"
  },
  "dependencies": {},
  "peerDependencies": {},
  "devDependencies": {
    "@opencode-ai/plugin": "^1.18.9",
    "@opencode-ai/sdk": "^1.18.9",
    "@types/bun": "^1.3.14",
    "@types/node": "^26.1.2",
    "tsup": "^8.5.1",
    "typescript": "^7.0.2"
  }
}
